import { Union } from "./fable_modules/fable-library-js.5.21.0/Types.js";
import { union_type, string_type } from "./fable_modules/fable-library-js.5.21.0/Reflection.js";
import { empty, singleton, collect, delay, toArray } from "./fable_modules/fable-library-js.5.21.0/Seq.js";

export class Kind extends Union {
    constructor(tag, fields) {
        super();
        this.tag = tag;
        this.fields = fields;
    }
    cases() {
        return ["Alpha", "Beta", "Other"];
    }
    static Alpha = new Kind(0, []);
    static Other = new Kind(2, []);
}

export function Kind_$reflection() {
    return union_type("Stress.ArrayComprehension.Kind", [], Kind, () => [[], [["Item", string_type]], []]);
}

export function ArrayComprehension(items) {
    return toArray(delay(() => collect((s) => ((s.length > 0) ? singleton(<span>
        {s}
    </span>) : empty()), items)));
}

